    'Half-yearly rate = 7%/2 = 3.5% = 0.035. Number of half-years in 18 months = 3. Amount = P(1 + r)^n = 200000 × (1.035)^3. Calculating: 1.035^3 ≈ 1.1087179. Multiplying: 200000 × 1.1087179 ≈ ₹2,21,743.58, which rounds to ₹2,21,744.',
